import sys
import heapq
from itertools import product

data = sys.stdin.read().split()
n = int(data[0])
a = [int(x) for x in data[1:1 + n]]

def solve(c):
    # c[j] = packages at distance j + 1 from the base. Dijkstra over states.
    start = tuple(c)
    goal = tuple([0] * n)
    dist = {start: 0}
    pq = [(0, start)]
    while pq:
        d, s = heapq.heappop(pq)
        if dist.get(s, 1 << 60) < d:
            continue
        if s == goal:
            return d
        for target in range(1, n + 1):
            avail = [j for j in range(target) if s[j] > 0]
            for mask in product((0, 1), repeat=len(avail)):
                if not any(mask):
                    continue
                t = list(s)
                for j, m in zip(avail, mask):
                    t[j] -= m
                t = tuple(t)
                nd = d + target
                if nd < dist.get(t, 1 << 60):
                    dist[t] = nd
                    heapq.heappush(pq, (nd, t))
    return 1 << 60

print(sum(a) + min(solve(a), solve(a[::-1])))

